//! The DDS type support `rustorb-idl -brust -Wbdds_only` generates for
//! `idl/DdsMapping.idl`, and `-Wbdds` for `idl/DdsCorba.idl` (checked in
//! under `generated/`, regenerated by `tools/generate-rust.sh`): payloads checked
//! octet by octet against the rules of DDS-XTypes 1.3 7.4.3.5.3, the key
//! hash examples of 7.6.8, round trips and type evolution.

#[allow(dead_code)]
#[path = "../generated/dds_mapping.rs"]
mod dds_mapping_idl;

#[allow(dead_code)]
#[path = "../generated/dds_corba.rs"]
mod dds_corba_idl;

use rustorb_typesupport::{ByteOrder, Encoding, Error, Extensibility, TopicType, md5};

use dds_mapping_idl::dds_mapping::*;

const ENCODINGS: [Encoding; 2] = [Encoding::Xcdr1, Encoding::Xcdr2];
const ORDERS: [ByteOrder; 2] = [ByteOrder::Big, ByteOrder::Little];

fn round_trip<T: TopicType + PartialEq + std::fmt::Debug>(v: &T) {
    for encoding in ENCODINGS {
        for order in ORDERS {
            let payload = v.to_payload(encoding, order).unwrap();
            assert_eq!(payload.len() % 4, 0);
            let back = T::from_payload(&payload)
                .unwrap_or_else(|e| panic!("{encoding:?} {order:?}: {e}: {payload:02x?}"));
            assert_eq!(&back, v, "{encoding:?} {order:?}");
        }
    }
}

// -- key hashes (DDS-XTypes 7.6.8) ---------------------------------------

#[test]
fn key_hash_example_1() {
    let v = KeyHash1 {
        id: 0x12345678,
        x: 10,
        y: 20,
    };
    assert_eq!(v.key_holder().unwrap(), [0x12, 0x34, 0x56, 0x78]);
    let mut expected = [0u8; 16];
    expected[..4].copy_from_slice(&[0x12, 0x34, 0x56, 0x78]);
    assert_eq!(v.key_hash().unwrap(), expected);
    const { assert!(KeyHash1::KEYED) };
}

#[test]
fn key_hash_example_2() {
    let v = KeyHash2 {
        label: "BLUE".into(),
        id: 0x123456789abcdef0,
        x: 10,
        y: 20,
    };
    assert_eq!(
        v.key_holder().unwrap(),
        [
            0x00, 0x00, 0x00, 0x05, 0x42, 0x4c, 0x55, 0x45, 0x00, 0x00, 0x00, 0x00, 0x12, 0x34,
            0x56, 0x78, 0x9a, 0xbc, 0xde, 0xf0
        ]
    );
    assert_eq!(
        v.key_hash().unwrap(),
        [
            0xf9, 0x1a, 0x59, 0xe3, 0x2e, 0x45, 0x35, 0xd9, 0xa6, 0x9c, 0xd5, 0xd9, 0xf5, 0xb6,
            0xe3, 0x6e
        ]
    );
}

#[test]
fn key_hash_example_3() {
    // The members of the key holders are in the order of their member
    // IDs: m_nested (30) before label (40).
    let v = KeyHash3 {
        label: "BLUE".into(),
        m_nested: KeyHash3Nested {
            m_long: 0x12345678,
            u: 10,
            w: 20,
        },
        x: 100,
        y: 200,
    };
    assert_eq!(
        v.key_holder().unwrap(),
        [
            0x12, 0x34, 0x56, 0x78, 0x00, 0x00, 0x00, 0x05, 0x42, 0x4c, 0x55, 0x45, 0x00
        ]
    );
    assert_eq!(
        v.key_hash().unwrap(),
        [
            0x37, 0x4b, 0x96, 0xe2, 0xe7, 0x27, 0x23, 0x7f, 0x01, 0x6c, 0xc4, 0xce, 0xbb, 0x6e,
            0xb7, 0x1e
        ]
    );
}

#[test]
fn key_hash_of_nested_keys_and_enums() {
    // Inner is reduced to its key (id), the enum is one octet
    // (@bit_bound(8)), and the 5 octets are the hash.
    let v = Outer {
        inner: Inner {
            id: 7,
            choice: Choice::Number(1),
        },
        color: Color::Black,
        by_color: ByColor::Red(1.5),
    };
    let mut expected = [0u8; 16];
    expected[..5].copy_from_slice(&[0, 0, 0, 7, 0xfd]);
    assert_eq!(v.key_hash().unwrap(), expected);
}

#[test]
fn key_hash_of_unbounded_keys_is_md5() {
    let v = Shape {
        color: "RED".into(),
        x: 1,
        y: 2,
        shapesize: 30,
    };
    let holder = [0, 0, 0, 4, b'R', b'E', b'D', 0];
    assert_eq!(v.key_holder().unwrap(), holder);
    assert_eq!(v.key_hash().unwrap(), md5(&holder));

    // A sequence<long, 4> takes up to 20 octets: hashed too.
    let v = Aliased { longs: vec![1, 2] };
    let holder = [0, 0, 0, 2, 0, 0, 0, 1, 0, 0, 0, 2];
    assert_eq!(v.key_holder().unwrap(), holder);
    assert_eq!(v.key_hash().unwrap(), md5(&holder));
}

#[test]
fn unkeyed_types_hash_all_their_members() {
    let v = Point { x: 1, y: 2 };
    const { assert!(!Point::KEYED) };
    assert_eq!(v.key_holder().unwrap(), [0, 0, 0, 1, 0, 0, 0, 2]);
}

// -- payloads octet by octet ---------------------------------------------

#[test]
fn final_struct_is_plain_cdr() {
    let v = Point { x: 1, y: 2 };
    // PLAIN_CDR, little endian.
    assert_eq!(
        v.to_payload(Encoding::Xcdr1, ByteOrder::Little).unwrap(),
        [0x00, 0x01, 0, 0, 1, 0, 0, 0, 2, 0, 0, 0]
    );
    // PLAIN_CDR2, big endian.
    assert_eq!(
        v.to_payload(Encoding::Xcdr2, ByteOrder::Big).unwrap(),
        [0x00, 0x06, 0, 0, 0, 0, 0, 1, 0, 0, 0, 2]
    );
}

#[test]
fn appendable_struct_has_a_dheader_in_xcdr2() {
    let v = Shape {
        color: "BLUE".into(),
        x: 1,
        y: 2,
        shapesize: 30,
    };
    assert_eq!(Shape::TYPE_NAME, "DdsMapping::Shape");
    assert_eq!(Shape::EXTENSIBILITY, Extensibility::Appendable);
    #[rustfmt::skip]
    let expected = [
        0x00, 0x09, 0x00, 0x00, // DELIMITED_CDR, little endian
        24, 0, 0, 0, // DHEADER
        5, 0, 0, 0, b'B', b'L', b'U', b'E', 0, 0, 0, 0, // color and padding
        1, 0, 0, 0,
        2, 0, 0, 0,
        30, 0, 0, 0,
    ];
    assert_eq!(
        v.to_payload(Encoding::Xcdr2, ByteOrder::Little).unwrap(),
        expected
    );
    // XCDR1 writes appendable types as final ones (rule 29).
    #[rustfmt::skip]
    let expected = [
        0x00, 0x01, 0x00, 0x00, // PLAIN_CDR, little endian
        5, 0, 0, 0, b'B', b'L', b'U', b'E', 0, 0, 0, 0,
        1, 0, 0, 0,
        2, 0, 0, 0,
        30, 0, 0, 0,
    ];
    assert_eq!(
        v.to_payload(Encoding::Xcdr1, ByteOrder::Little).unwrap(),
        expected
    );
}

#[test]
fn hashed_member_ids_in_emheaders() {
    // DDS-XTypes 7.3.1.2.1.1 example 2: ID(color) = 0x0FA5DD70,
    // ID(size) = 0x047790DA.
    let v = AutoidHash {
        color: "red".into(),
        size: 5,
    };
    #[rustfmt::skip]
    let expected = [
        0x00, 0x0a, 0x00, 0x00, // PL_CDR2, big endian
        0, 0, 0, 20, // DHEADER
        0x3f, 0xa5, 0xdd, 0x70, // EMHEADER: LC 3 (8 octets), color
        0, 0, 0, 4, b'r', b'e', b'd', 0,
        0x24, 0x77, 0x90, 0xda, // EMHEADER: LC 2 (4 octets), size
        0, 0, 0, 5,
    ];
    assert_eq!(
        v.to_payload(Encoding::Xcdr2, ByteOrder::Big).unwrap(),
        expected
    );
    round_trip(&v);
}

#[test]
fn mutable_struct_is_a_parameter_list_in_xcdr1() {
    let v = Evolving {
        a: 7,
        b: None,
        c: vec![],
        far: -1,
    };
    #[rustfmt::skip]
    let expected = [
        0x00, 0x02, 0x00, 0x00, // PL_CDR, big endian
        0x00, 0x01, 0x00, 0x04, 0, 0, 0, 7, // a
        // b is absent: no parameter
        0x00, 0x03, 0x00, 0x04, 0, 0, 0, 0, // c, empty
        // far: ID 0x4000 needs an extended header, must understand
        0x7f, 0x01, 0x00, 0x08, 0x40, 0x00, 0x40, 0x00, 0, 0, 0, 2, 0xff, 0xff, 0, 0,
        0x7f, 0x02, 0x00, 0x00, // PID_LIST_END
    ];
    assert_eq!(
        v.to_payload(Encoding::Xcdr1, ByteOrder::Big).unwrap(),
        expected
    );
    round_trip(&v);
    round_trip(&Evolving {
        a: 1,
        b: Some("b".into()),
        c: vec![Point { x: 1, y: 2 }, Point { x: 3, y: 4 }],
        far: 9,
    });
}

#[test]
fn optional_members_of_final_types() {
    let absent = OptionalFinal { a: None, b: 5 };
    let present = OptionalFinal { a: Some(3), b: 5 };
    // XCDR1: a parameter header, of length 0 when absent.
    assert_eq!(
        absent
            .to_payload(Encoding::Xcdr1, ByteOrder::Little)
            .unwrap(),
        [0x00, 0x01, 0, 0, 0, 0, 0, 0, 5, 0, 0, 0]
    );
    assert_eq!(
        present
            .to_payload(Encoding::Xcdr1, ByteOrder::Little)
            .unwrap(),
        [0x00, 0x01, 0, 0, 0, 0, 4, 0, 3, 0, 0, 0, 5, 0, 0, 0]
    );
    // XCDR2: a boolean.
    assert_eq!(
        absent
            .to_payload(Encoding::Xcdr2, ByteOrder::Little)
            .unwrap(),
        [0x00, 0x07, 0, 0, 0, 0, 0, 0, 5, 0, 0, 0]
    );
    assert_eq!(
        present
            .to_payload(Encoding::Xcdr2, ByteOrder::Little)
            .unwrap(),
        [0x00, 0x07, 0, 0, 1, 0, 0, 0, 3, 0, 0, 0, 5, 0, 0, 0]
    );
    round_trip(&absent);
    round_trip(&present);
}

#[test]
fn unions() {
    #[rustfmt::skip]
    let expected = [
        0x00, 0x09, 0x00, 0x00, // DELIMITED_CDR, little endian
        8, 0, 0, 0, // DHEADER
        1, 0, 0, 0, // discriminator
        5, 0, 0, 0, // number
    ];
    assert_eq!(
        Choice::Number(5)
            .to_payload(Encoding::Xcdr2, ByteOrder::Little)
            .unwrap(),
        expected
    );
    round_trip(&Choice::Number(5));
    round_trip(&Choice::Text(3, "three".into()));
    round_trip(&Choice::Point(-1, Point { x: 1, y: 2 }));
    // A discriminator that is not one of the labels of the member.
    assert_eq!(
        Choice::Text(1, "one".into()).to_payload(Encoding::Xcdr2, ByteOrder::Little),
        Err(Error::InvalidDiscriminator)
    );
    // The enum discriminator is one octet (@bit_bound(8)).
    assert_eq!(
        ByColor::Red(0.5)
            .to_payload(Encoding::Xcdr2, ByteOrder::Big)
            .unwrap(),
        [0x00, 0x06, 0, 0, 0, 0, 0, 0, 0x3f, 0xe0, 0, 0, 0, 0, 0, 0]
    );
    round_trip(&ByColor::Green(Point { x: 1, y: 2 }));
    round_trip(&ByColor::Default(Color::Blue));
}

// -- enums and bitmasks --------------------------------------------------

#[test]
fn enums_are_written_as_their_values() {
    assert_eq!(Color::default(), Color::Black);
    assert_eq!(Color::Green.value(), 10);
    assert_eq!(Color::Blue.value(), 11);
    assert_eq!(Color::from_value(-3), Some(Color::Black));
    assert_eq!(Color::from_value(1), None);
    let v = Outer {
        inner: Inner {
            id: 1,
            choice: Choice::Number(2),
        },
        color: Color::Green,
        by_color: ByColor::Red(1.0),
    };
    round_trip(&v);
    // An unknown enum value is an error.
    let mut payload = v.to_payload(Encoding::Xcdr1, ByteOrder::Big).unwrap();
    let at = payload.iter().rposition(|&b| b == 10).unwrap();
    payload[at] = 99;
    assert!(Outer::from_payload(&payload).is_err());
}

#[test]
fn bitmasks() {
    let f = Flags::READ | Flags::EXEC;
    assert_eq!(f.bits(), 0x0801);
    assert!(f.contains(Flags::EXEC));
    assert!(!f.contains(Flags::WRITE));
    let mut g = Flags::EMPTY;
    g |= Flags::WRITE;
    assert_eq!(g & f, Flags::EMPTY);
}

// -- everything ----------------------------------------------------------

fn everything() -> Everything {
    Everything {
        b: true,
        o: 0xab,
        i8v: -5,
        s: -300,
        us: 60000,
        l: -70000,
        ul: 4_000_000_000,
        ll: -(1 << 40),
        ull: 1 << 63,
        f: 1.5,
        d: -2.25,
        c: 'é',
        wc: 'あ',
        str: "hello".into(),
        bstr: "bounded".into(),
        wstr: "wide ✓".into(),
        bwstr: "four".into(),
        longs: vec![1, -2, 3],
        octets: vec![1, 2, 3, 4, 5],
        strings: vec!["a".into(), "".into(), "ccc".into()],
        points: vec![Point { x: 1, y: 2 }],
        matrix: [[1, 2, 3], [4, 5, 6]],
        corners: [Point { x: -1, y: -2 }, Point { x: 3, y: 4 }],
        color: Color::Blue,
        flags: Flags::READ | Flags::WRITE,
        maybe: Some(42),
        maybe_point: None,
        boxed: Box::new(Point { x: 9, y: 8 }),
    }
}

#[test]
fn everything_round_trips() {
    round_trip(&everything());
    round_trip(&Everything::default());
    let mut v = everything();
    v.maybe = None;
    v.maybe_point = Some(Point { x: 5, y: 6 });
    round_trip(&v);
}

#[test]
fn bounds_and_characters_are_checked() {
    let mut v = everything();
    v.bstr = "too long!".into();
    assert_eq!(
        v.to_payload(Encoding::Xcdr2, ByteOrder::Little),
        Err(Error::BoundExceeded { bound: 8, len: 9 })
    );
    let mut v = everything();
    v.strings.push("d".into());
    assert!(matches!(
        v.to_payload(Encoding::Xcdr1, ByteOrder::Little),
        Err(Error::BoundExceeded { bound: 3, len: 4 })
    ));
    let mut v = everything();
    v.c = 'あ';
    assert_eq!(
        v.to_payload(Encoding::Xcdr2, ByteOrder::Little),
        Err(Error::InvalidChar(0x3042))
    );
}

#[test]
fn payload_format_must_match_the_type() {
    let payload = Point { x: 1, y: 2 }
        .to_payload(Encoding::Xcdr2, ByteOrder::Little)
        .unwrap();
    assert!(matches!(
        Shape::from_payload(&payload),
        Err(Error::FormatMismatch(_))
    ));
    assert_eq!(
        Point { x: 1, y: 2 }.to_payload(Encoding::Giop1_2, ByteOrder::Little),
        Err(Error::NotXcdr)
    );
}

// -- type evolution ------------------------------------------------------

#[test]
fn mutable_types_evolve() {
    let v2 = EvolvingV2 {
        a: 1,
        b: Some("b".into()),
        c: vec![Point { x: 1, y: 2 }],
        far: 3,
        added: 4.5,
    };
    let v1 = Evolving {
        a: 1,
        b: Some("b".into()),
        c: vec![Point { x: 1, y: 2 }],
        far: 3,
    };
    for encoding in ENCODINGS {
        for order in ORDERS {
            // A newer writer: the member the reader does not know is
            // skipped.
            let payload = v2.to_payload(encoding, order).unwrap();
            assert_eq!(Evolving::from_payload(&payload).unwrap(), v1);
            // An older writer: the missing member takes its default.
            let payload = v1.to_payload(encoding, order).unwrap();
            let back = EvolvingV2::from_payload(&payload).unwrap();
            assert_eq!(back.added, 0.0);
            assert_eq!(back.c, v1.c);
            // A member that must be understood and is not.
            assert_eq!(
                EvolvingV0::from_payload(&payload),
                Err(Error::UnknownMustUnderstand(0x4000))
            );
            // A missing member is defaulted, an optional one absent.
            let v0 = EvolvingV0 { a: 5, c: vec![] };
            let back = Evolving::from_payload(&v0.to_payload(encoding, order).unwrap()).unwrap();
            assert_eq!(
                back,
                Evolving {
                    a: 5,
                    b: None,
                    c: vec![],
                    far: 0,
                }
            );
        }
    }
}

#[test]
fn appendable_types_evolve_in_xcdr2() {
    let grown = Grown { a: 1, b: 2 };
    for order in ORDERS {
        let payload = grown.to_payload(Encoding::Xcdr2, order).unwrap();
        assert_eq!(Small::from_payload(&payload).unwrap(), Small { a: 1 });
        let payload = Small { a: 1 }.to_payload(Encoding::Xcdr2, order).unwrap();
        assert_eq!(Grown::from_payload(&payload).unwrap(), Grown { a: 1, b: 0 });
    }
}

// -- topic types ---------------------------------------------------------

fn type_name<T: TopicType>() -> &'static str {
    T::TYPE_NAME
}

#[test]
fn topic_types() {
    assert_eq!(type_name::<KeyHash3>(), "DdsMapping::KeyHash3");
    // @topic overrides @default_nested.
    assert_eq!(type_name::<nested::Shown>(), "DdsMapping::Nested::Shown");
    assert_eq!(type_name::<Outer>(), "DdsMapping::Outer");
    const { assert!(Outer::KEYED) };
    const { assert!(!Choice::KEYED) };
    assert_eq!(Evolving::EXTENSIBILITY, Extensibility::Mutable);
}

// -- CORBA and DDS impls on the same types --------------------------------

#[test]
fn corba_and_dds_share_the_rust_types() {
    use dds_corba_idl::dds_corba::{Kind, Sample, Value};
    use rustorb_core::idl::IdlType;

    let v = Sample {
        id: 3,
        kind: Kind::Square,
        label: "sq".into(),
        values: vec![1.0, 2.0],
    };
    round_trip(&v);
    round_trip(&Value::Radius(2.5));
    assert_eq!(Sample::TYPE_NAME, "DdsCorba::Sample");
    assert_eq!(v.key_hash().unwrap()[..4], [0, 0, 0, 3]);
    // The CORBA side: a TypeCode, and an any holding the value.
    assert_eq!(
        <Sample as IdlType>::type_code().id().unwrap(),
        Sample::REPOSITORY_ID
    );
    let any = rustorb_core::Any::insert::<Sample>(&v).unwrap();
    assert_eq!(any.extract::<Sample>().unwrap(), v);
}
